#include <stdio.h>

int contains(const int values[], int count, int target) {
    for (int i = 0; i < count; i++) {
        if (values[i] == target) {
            return 1;
        }
    }
    return 0;
}

int main() {
    int numbers[] = {5, 5, 6, 6, 6, 7, 5};
    int unique[7];
    int count = 0;
    for (int i = 0; i < 7; i++) {
        if (!contains(unique, count, numbers[i])) {
            unique[count++] = numbers[i];
        }
    }
    for (int i = 0; i < count; i++) {
        printf("%d\n", unique[i]);
    }
    return 0;
}
